"use strict";(self.webpackChunk_1stblue_github_io=self.webpackChunk_1stblue_github_io||[]).push([[6114],{8502:e=>{e.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"v2.5-release-notes","metadata":{"permalink":"/fr/blog/v2.5-release-notes","editUrl":"https://github.com/1stblue/1stblue.github.io/tree/deploy-bluepipe-landing-page/blog/2025/2025-03-31-v2.5-released.md","source":"@site/blog/2025/2025-03-31-v2.5-released.md","title":"Release Notes (v2.5)","description":"\u65b0\u7279\u6027","date":"2025-03-31T00:00:00.000Z","tags":[{"inline":true,"label":"Release Notes","permalink":"/fr/blog/tags/release-notes"},{"inline":true,"label":"v2.5","permalink":"/fr/blog/tags/v-2-5"}],"readingTime":0.89,"hasTruncateMarker":true,"authors":[{"name":"aleafs","title":"\u5927\u9f84\u7a0b\u5e8f\u5458","url":"https://github.com/aleafs","imageURL":"https://avatars.githubusercontent.com/u/535479","key":"aleafs","page":null}],"frontMatter":{"slug":"v2.5-release-notes","authors":["aleafs"],"image":"/img/blog-static/20250331/v2.5-cover.jpeg","tags":["Release Notes","v2.5"]},"unlisted":false,"nextItem":{"title":"\u6784\u5efa\u8de8\u7f51\u7edc\u6570\u636e\u7ba1\u9053\u6700\u4f73\u5b9e\u8df5","permalink":"/fr/blog/bluepipe-with-lakehouse"}},"content":"## \u65b0\u7279\u6027\\n\\n\u6b64\u7248\u672c\u4ee5`MySQL`\u4e3a\u4f8b\uff0c\u5b9e\u9a8c\u6027\u5730\u652f\u6301\u4e86\u5728\u76f8\u540c\u7c7b\u578b\u6570\u636e\u5e93\u4e4b\u95f4\u8fc1\u79fb\u89c6\u56fe\u3001\u89e6\u53d1\u5668\u3001\u5b58\u50a8\u8fc7\u7a0b\u3001\u51fd\u6570\u3001\u7528\u6237\u548c\u6743\u9650\u7b49\u3002\\n\\n\u6b64\u7279\u6027\u5bf9\u4e8e\u65b0\u5efa/\u91cd\u5efa\u5907\u5e93\uff0c\u6216\u8005\u8fdb\u884c\u6574\u4e2a\u6570\u636e\u5e93\u5b9e\u4f8b\u8fc1\u79fb\u975e\u5e38\u6709\u5e2e\u52a9\uff0c\u6b22\u8fce\u4f53\u9a8c\u3002\\n\\n\x3c!-- truncate --\x3e\\n\\n![\u642d\u5efaMySQL\u5907\u5e93](/img/blog-static/20250331/mysql-migration.png)\\n\\n## \u8fde\u63a5\u5668\\n\\n### \u4f18\u5316 MySQL \u8fde\u63a5\u5668\\n\\n* \u652f\u6301\u5728`MySQL`\u4e4b\u95f4\u8fc1\u79fb\u89c6\u56fe\u3001\u89e6\u53d1\u5668\u3001\u5b58\u50a8\u8fc7\u7a0b\u3001\u51fd\u6570\u3001\u7528\u6237\u548c\u6743\u9650\uff1b\\n\\n### \u4f18\u5316 Oracle \u8fde\u63a5\u5668\\n\\n* `CDC` \u652f\u6301 `PDB` \u67b6\u6784\uff1b\\n\\n### \u65b0\u589e SQL Server \u8fde\u63a5\u5668\\n\\n* \u652f\u6301\u901a\u8fc7\u6279\u91cf\u65b9\u5f0f\u8bfb\u53d6\u6570\u636e\uff1b\\n* \u6682\u672a\u652f\u6301\u57fa\u4e8e\u65e5\u5fd7\u8ba2\u9605\u7684 CDC \u80fd\u529b\uff1b\\n* \u6682\u672a\u652f\u6301\u6570\u636e\u5199\u5165\u80fd\u529b\u3002"},{"id":"bluepipe-with-lakehouse","metadata":{"permalink":"/fr/blog/bluepipe-with-lakehouse","editUrl":"https://github.com/1stblue/1stblue.github.io/tree/deploy-bluepipe-landing-page/blog/2024/2024-06-21-with-lakehouse.md","source":"@site/blog/2024/2024-06-21-with-lakehouse.md","title":"\u6784\u5efa\u8de8\u7f51\u7edc\u6570\u636e\u7ba1\u9053\u6700\u4f73\u5b9e\u8df5","description":"\u672c\u6587\u4ee5\u4e91\u5668 Lakehouse \u4e3a\u4f8b\uff0c\u4ecb\u7ecd\u5229\u7528bluepipe\u6784\u5efa\u8de8\u7f51\u7edc\u7684\u6570\u636e\u590d\u5236\u6700\u4f73\u5b9e\u8df5\u3002","date":"2024-06-21T00:00:00.000Z","tags":[{"inline":true,"label":"lakehouse","permalink":"/fr/blog/tags/lakehouse"},{"inline":true,"label":"network","permalink":"/fr/blog/tags/network"},{"inline":true,"label":"Oracle","permalink":"/fr/blog/tags/oracle"}],"readingTime":3.17,"hasTruncateMarker":true,"authors":[{"name":"aleafs","title":"\u5927\u9f84\u7a0b\u5e8f\u5458","url":"https://github.com/aleafs","imageURL":"https://avatars.githubusercontent.com/u/535479","key":"aleafs","page":null}],"frontMatter":{"slug":"bluepipe-with-lakehouse","authors":["aleafs"],"image":"/img/blog-static/cover-bridge.jpeg","tags":["lakehouse","network","Oracle"]},"unlisted":false,"prevItem":{"title":"Release Notes (v2.5)","permalink":"/fr/blog/v2.5-release-notes"}},"content":"\u672c\u6587\u4ee5[\u4e91\u5668](https://yunqi.tech/) `Lakehouse` \u4e3a\u4f8b\uff0c\u4ecb\u7ecd\u5229\u7528`bluepipe`\u6784\u5efa\u8de8\u7f51\u7edc\u7684\u6570\u636e\u590d\u5236\u6700\u4f73\u5b9e\u8df5\u3002\\n\\n\u5982\u4e0b\u56fe\uff0c\u5ba2\u6237\u4e1a\u52a1\u7cfb\u7edf\u90e8\u7f72\u5728\u79c1\u6709 IDC \u4e2d\uff0c\u800c`Lakehouse`\u4f5c\u4e3a\u591a\u79df\u6237\u6e56\u4ed3\u670d\u52a1\u90e8\u7f72\u5728\u4e91\u4e0a\u3002\u6570\u636e\u9700\u8981\u4ece`Oracle`\u540c\u6b65\u5230`Lakehouse`\\n\uff0c\u6211\u4eec\u63a8\u8350\u5c06`bluepipe`\u90e8\u7f72\u5728\u5ba2\u6237 IDC \u4e2d\uff0c**\u63a8**\u6570\u636e\u5230`Lakehouse`\u3002\\n\x3c!-- truncate --\x3e\\n\\n![Oracle to Lakehouse](/img/blog-static/cross-network-pipe.png)\\n\\n## \u65b9\u6848\u4f18\u52bf\\n\\n### \u5f00\u7bb1\u5373\u7528\uff0c10 \u5206\u949f\u5b8c\u6210\u914d\u7f6e\\n\\n* `bluepipe`\u51e0\u4e4e\u53ef\u4ee5\u8fd0\u884c\u5728\u4efb\u4f55`Linux`\u7cfb\u7edf\u4e2d\uff0c\u652f\u6301`x86`\u548c`arm`\u82af\u7247\uff1b\u5e38\u89c1\u7684\u673a\u67b6\u5f0f\u670d\u52a1\u5668\u3001\u7b14\u8bb0\u672c\u7535\u8111\uff0c\u751a\u81f3\u6811\u8393\u6d3e\u90fd\u53ef\u4ee5\u7528\u6765\u90e8\u7f72\uff1b\\n* \u6781\u7b80\u7684\u914d\u7f6e\u8fc7\u7a0b\uff0c\u9ed8\u8ba4\u53c2\u6570\u5373\u53ef\u8fbe\u5230\u6700\u4f73\u6027\u80fd\u3002\\n\\n### \u5168\u3001\u589e\u91cf\u4e00\u4f53\u5316\uff0c\u65e0\u9700\u8fd0\u7ef4\u5e72\u9884\\n\\n* \u5168\u91cf\u540c\u6b65\u4e0e\u589e\u91cf\u540c\u6b65\u6df1\u5ea6\u534f\u540c\uff0c\u51e0\u4e4e\u65e0\u9700\u65e5\u5e38\u8fd0\u7ef4\u64cd\u4f5c\uff1b\\n* \u9ad8\u6548\u7684\u6570\u636e\u6bd4\u5bf9\u4e0e\u70ed\u4fee\u590d\u6280\u672f\uff0c\u59cb\u7ec8\u4fdd\u8bc1\u6570\u636e\u4e00\u81f4\uff1b\\n* \u9ad8\u5ea6\u9c81\u68d2\u7684`Schema Evolution`\u3002\\n\\n### \u63a8\u6570\u636e\uff0c\u800c\u4e0d\u662f\u66b4\u9732\u7aef\u53e3\\n\\n* `bluepipe`\u4e0e\u60a8\u7684\u6570\u636e\u5e93\u4e00\u8d77\u90e8\u7f72\u5728\u60a8\u7684\u5185\u7f51\uff0c\u65e0\u9700\u5bf9\u5916\u66b4\u9732\u7aef\u53e3\uff1b\\n* \u5f39\u6027`buffer size`\u6280\u672f\uff0c\u5728`\u541e\u5410(Throughput)`\u548c`\u5ef6\u8fdf(latency)`\u4e4b\u95f4\u81ea\u52a8\u5e73\u8861\u3002\\n\\n## Oracle \u94fe\u8def\u7684\u72ec\u7279\u4f18\u52bf\\n\\n`bluepipe`\u57fa\u4e8e`Oracle LogMiner`\u5b9e\u73b0\u5bf9\u53d8\u66f4\u6570\u636e\u7684\u6355\u6349\u3002\u4e0e\u6b64\u540c\u65f6\uff0c\u5728\u4ee5\u4e0b\u51e0\u4e2a\u65b9\u9762\u505a\u4e86\u6df1\u5ea6\u4f18\u5316\uff1a\\n\\n### \u5bf9 DDL \u884c\u4e3a\u7684\u6df1\u5ea6\u517c\u5bb9\\n\\n\u5728`LogMiner`\u9ed8\u8ba4\u7b56\u7565\u4e0b\uff0c\u5f53\u53d1\u751f`DDL`\u884c\u4e3a\u540e\uff0c\u76f8\u5173\u8868\u4e0a\u540e\u7eed\u7684`DML`\u64cd\u4f5c\u5747\u65e0\u6cd5\u6b63\u786e\u89e3\u6790\uff0c\u4ece\u800c\u5bfc\u81f4\u65e0\u6cd5\u6b63\u786e\u6355\u6349\u5230\u53d8\u66f4\u3002\\n\\n`bluepipe`\u7ef4\u62a4\u4e86\u5b57\u5178\u6587\u4ef6\u7684\u81ea\u52a8\u6784\u5efa\u7b56\u7565\uff0c\u4fdd\u8bc1\u8868\u7ed3\u6784\u53d8\u66f4\u540e\u4ecd\u7136\u80fd\u6355\u6349\u5230\u6b63\u786e\u7684\u589e\u91cf\u6570\u636e\u3002\\n\\n### \u5927\u4e8b\u52a1\u4f18\u5316\\n\\n`Oracle Redo Log`\u4e2d\u8bb0\u5f55\u4e86\u5b8c\u6574\u7684\u4e8b\u52a1(`Transaction`)\u8fc7\u7a0b\uff0c\u800c\u4e1a\u52a1\u4e0a\u901a\u5e38\u4ec5\u5e0c\u671b\u62ff\u5230`commit`\\n\u4e4b\u540e\u7684\u6570\u636e\uff0c\u56e0\u6b64\uff0c\u9700\u8981\u5728\u4f20\u8f93\u8fc7\u7a0b\u4e2d\u4f7f\u7528`buffer`\u6765\u6682\u5b58\u5c1a\u672a`commit`\u7684\u53d8\u66f4\u8bb0\u5f55\u3002\\n\\n`bluepipe`\u57fa\u4e8e\u72ec\u7279\u7684\u5185\u5b58\u7ba1\u7406\u6280\u672f\uff0c\u5355\u8282\u70b9\u4e0a\u4e5f\u80fd\u8f7b\u677e\u5e94\u5bf9\u5343\u4e07\u91cf\u7ea7\u7684\u5927\u4e8b\u52a1\u3002\\n\\n### \u5168\u9762\u652f\u6301\u540d\u79f0\u8d85\u8fc7 30 \u5b57\u7b26\u7684\u8868\\n\\n`Oracle 12.2`\u7248\u672c\u4e4b\u540e\uff0c\u5bf9\u8868\u540d\u3001\u5b57\u6bb5\u540d\u7684\u6700\u5927\u957f\u5ea6\u652f\u6301\u5230\u4e86 128 \u5b57\u8282\u3002\\n\u4f46\u56e0\u4e3a\u79cd\u79cd\u539f\u56e0\uff0c`LogMiner`\u5bf9\u4e8e\u65e0`OGG LICENSE`\u7684\u5b9e\u4f8b\uff0c\u81f3\u4eca\u4ecd\u4e0d\u652f\u6301\u5bf9\u5305\u542b\u957f\u540d\u79f0\u7684\u8868\u7684 DML\\n\u89e3\u6790\uff0c\u8be6\u60c5\u53c2\u8003[\u5b98\u65b9\u6587\u6863](https://docs.oracle.com/en/database/oracle/oracle-database/19/sutil/oracle-logminer-utility.html)\u3002\\n\\n`bluepipe`\u57fa\u4e8e\u9ad8\u6548\u7684\u6d41\u6279\u878d\u5408\u6280\u672f\uff0c\u5168\u9762\u652f\u6301\u4e86\u6b64\u79cd\u60c5\u51b5\u4e0b\u7684\u589e\u91cf\u6570\u636e\u6355\u6349\u4e0e\u6295\u9012\u3002\\n\\n### \u9002\u914d\u652f\u6301 RAC \u67b6\u6784"}]}}')}}]);